229	KVEventBatch *parse_kv_event_batch(const void *payload, size_t length)
230	{
231	    msgpack_unpacked result;
232	    msgpack_unpacked_init(&result);
233	
234	    if (msgpack_unpack_next(&result, (const char *)payload, length, NULL) != MSGPACK_UNPACK_SUCCESS)
235	    {
236	        msgpack_unpacked_destroy(&result);
237	        return NULL;
238	    }
239	
240	    const msgpack_object *obj = &result.data;
241	    if (obj->type != MSGPACK_OBJECT_ARRAY || obj->via.array.size < 2)
242	    {
243	        msgpack_unpacked_destroy(&result);
244	        return NULL;
245	    }
246	
247	    KVEventBatch *batch = malloc(sizeof(KVEventBatch));
248	    if (!batch)
249	    {
250	        msgpack_unpacked_destroy(&result);
251	        return NULL;
252	    }
253	    memset(batch, 0, sizeof(KVEventBatch));
254	    const msgpack_object_array *array = &obj->via.array;
255	
256	    // Timestamp
257	    if (array->ptr[0].type == MSGPACK_OBJECT_FLOAT)
258	        batch->ts = array->ptr[0].via.f64;
259	    else if (array->ptr[0].type == MSGPACK_OBJECT_POSITIVE_INTEGER)
260	        batch->ts = array->ptr[0].via.u64;
261	    else
262	        batch->ts = 0;
263	
264	    // Events
265	    if (array->ptr[1].type == MSGPACK_OBJECT_ARRAY)
266	    {
267	        size_t n = array->ptr[1].via.array.size;
268	        batch->events_count = n;
269	        batch->events = malloc(n * sizeof(KVCacheEvent *));
270	        if (!batch->events)
271	        {
272	            batch->events_count = 0;
273	            msgpack_unpacked_destroy(&result);
274	            return batch;
275	        }
276	        for (size_t j = 0; j < n; ++j)
277	        {
278	            KVCacheEvent *event = malloc(sizeof(KVCacheEvent));
279	            if (!event)
280	            {
281	                batch->events[j] = NULL;
282	                continue;
283	            }
284	            memset(event, 0, sizeof(KVCacheEvent));
285	            if (parse_kv_event(&array->ptr[1].via.array.ptr[j], event) == 0)
286	            {
287	                batch->events[j] = event;
288	            }
289	            else
290	            {
291	                free(event);
292	                batch->events[j] = NULL;
293	            }
294	        }
295	    }
296	
297	    msgpack_unpacked_destroy(&result);
298	    return batch;
299	}
300	
301	void free_kv_event_batch(KVEventBatch *batch)
302	{
303	    if (!batch)
304	        return;
305	    for (size_t i = 0; i < batch->events_count; i++)
306	    {
307	        if (batch->events[i])
308	        {
309	            KVCacheEvent *event = batch->events[i];
310	            if (event->type == KV_EVENT_BLOCK_STORED)
311	            {
312	                free(event->data.block_stored.block_hashes);
313	                free(event->data.block_stored.token_ids);
314	                free(event->data.block_stored.medium);
315	                free(event->data.block_stored.lora_name);
316	            }
317	            else if (event->type == KV_EVENT_BLOCK_REMOVED)
318	            {
319	                free(event->data.block_removed.block_hashes);
320	                free(event->data.block_removed.medium);
321	            }
322	            free(event);
323	        }
324	    }
325	    free(batch->events);
326	    free(batch);
327	}
