10	ngx_int_t omni_proxy_schedule_encode(omni_global_state_t *gs, omni_req_t *req, omni_req_context_t *ctx)
11	{
12	    if (gs->num_encode_endpoints == 0) {
13	        return NGX_DECLINED;
14	    }
15	
16	    uint32_t selected = UINT32_MAX;
17	    uint32_t least_load = UINT32_MAX;
18	    uint32_t least_running = UINT32_MAX;
19	    uint32_t cnt = 0;
20	
21	    for (uint32_t m = gs->last_selected_encode;
22	         m < MAX_ENCODE_UPSTREAMS + gs->last_selected_encode && cnt < gs->num_encode_endpoints; m++) {
23	        uint32_t j = m % MAX_ENCODE_UPSTREAMS;
24	        omni_upstream_encode_t *encode = &gs->encode_states[j];
25	        if (encode->comm.status != STATUS_ENABLE) {
26	            if (encode->comm.status == STATUS_UNUSED) {
27	                m = MAX_ENCODE_UPSTREAMS - 1;
28	            }
29	            continue;
30	        }
31	        cnt++;
32	        uint32_t load_tokens = encode->num_tokens;
33	        uint32_t running = encode->num_running;
34	        if (load_tokens < least_load || (load_tokens == least_load && running < least_running)) {
35	            least_load = load_tokens;
36	            least_running = running;
37	            selected = j;
38	            if (least_load == 0 && least_running == 0) {
39	                break;
40	            }
41	        }
42	    }
43	
44	    if (selected == UINT32_MAX) {
45	        return NGX_ERROR;
46	    }
47	
48	    req->encode_upstream_endpoint_idx = (uint16_t)selected;
49	    gs->last_selected_encode = (uint16_t)(selected + 1);
50	    req->has_encode_sched = true;
51	    uint32_t encode_items = (req->encode_item_count > 0) ? req->encode_item_count : ctx->encoder_item_count;
52	    if (encode_items == 0) {
53	        encode_items = 1;
54	    }
55	    ngx_atomic_fetch_add(&gs->encode_states[selected].num_running, 1);
56	    ngx_atomic_fetch_add(&gs->encode_states[selected].num_tokens, encode_items);
57	    ngx_atomic_fetch_add(&gs->encode_states[selected].comm.ref, 1);
58	
59	    struct timeval tv;
60	    omni_get_current_time(&tv);
61	    req->metrics.time_encode_scheduled = tv;
62	
63	    ngx_log_error(NGX_LOG_INFO, omni_get_http_request(req)->connection->log, 0,
64	                  "[Encoder-%d] Schedule to: %d (items=%ui, load=%ui)",
65	                  req->slot_index,
66	                  req->encode_upstream_endpoint_idx,
67	                  encode_items,
68	                  gs->encode_states[selected].num_tokens);
69	
70	    return NGX_OK;
71	}
