73	void omni_scheduler_record_prefill_batch_stat(omni_global_state_t *gs,
74	                                              uint32_t batch_size,
75	                                              ngx_msec_t duration)
76	{
77	    if (gs == NULL || batch_size == 0 || duration == 0)
78	    {
79	        ngx_log_error(NGX_LOG_INFO, ngx_cycle->log, 0,
80	                      "[PrefillStat] skip invalid input: gs=%p batch_size=%ui duration=%M",
81	                      gs, batch_size, duration);
82	        return;
83	    }
84	
85	    if (duration < 10 || duration > 600000)
86	    {
87	        ngx_log_error(NGX_LOG_INFO, ngx_cycle->log, 0,
88	                      "[PrefillStat] skip abnormal duration=%M for batch_size=%ui",
89	                      duration, batch_size);
90	        return;
91	    }
92	
93	    if (batch_size > OMNI_PREFILL_BATCH_STATS_MAX)
94	    {
95	        ngx_log_error(NGX_LOG_INFO, ngx_cycle->log, 0,
96	                      "[PrefillStat] batch_size %ui > MAX %ui, clamp to MAX",
97	                      batch_size, OMNI_PREFILL_BATCH_STATS_MAX);
98	        batch_size = OMNI_PREFILL_BATCH_STATS_MAX;
99	    }
100	
101	    omni_prefill_batch_stats_bucket_t *bucket = &gs->prefill_batch_stats.buckets[batch_size];
102	
103	    if (bucket->count < OMNI_PREFILL_BATCH_STATS_WINDOW)
104	    {
105	        bucket->durations[bucket->count] = duration;
106	        bucket->total += (uint64_t)duration;
107	        bucket->count++;
108	
109	        ngx_log_error(NGX_LOG_INFO, ngx_cycle->log, 0,
110	                      "[PrefillStat] batch=%ui append duration=%M total=%uL count=%ui avg=%M",
111	                      batch_size,
112	                      duration,
113	                      bucket->total,
114	                      bucket->count,
115	                      (ngx_msec_t)((bucket->total + (bucket->count / 2)) / bucket->count));
116	
117	        if (bucket->count == OMNI_PREFILL_BATCH_STATS_WINDOW)
118	        {
119	            bucket->cursor = 0;
120	            ngx_log_error(NGX_LOG_INFO, ngx_cycle->log, 0,
121	                          "[PrefillStat] batch=%ui window full, reset cursor=0", batch_size);
122	        }
123	    }
124	    else
125	    {
126	        uint32_t pos = bucket->cursor;
127	        ngx_msec_t old = bucket->durations[pos];
128	
129	        bucket->total -= (uint64_t)old;
130	        bucket->durations[pos] = duration;
131	        bucket->total += (uint64_t)duration;
132	        bucket->cursor = (pos + 1) % OMNI_PREFILL_BATCH_STATS_WINDOW;
133	
134	        ngx_log_error(NGX_LOG_INFO, ngx_cycle->log, 0,
135	                      "[PrefillStat] batch=%ui replace pos=%ui old=%M new=%M cursor=%ui total=%uL",
136	                      batch_size, pos, old, duration, bucket->cursor, bucket->total);
137	    }
138	
139	    if (bucket->count != 0)
140	    {
141	        bucket->cached_average =
142	            (ngx_msec_t)((bucket->total + (uint64_t)(bucket->count / 2)) / bucket->count);
143	
144	        ngx_log_error(NGX_LOG_INFO, ngx_cycle->log, 0,
145	                      "[PrefillStat] batch=%ui new avg=%M (count=%ui window=%ui)",
146	                      batch_size, bucket->cached_average,
147	                      bucket->count, OMNI_PREFILL_BATCH_STATS_WINDOW);
148	    }
149	}
150	
151	
152	#define OMNI_SCHED_EXEC_TIME_INCREMENT ((ngx_msec_t)50)
153	#define OMNI_SCHED_EXEC_MAX_TIME       ((ngx_msec_t)30000)
154	#define OMNI_SCHED_INFLITE_TIME        ((ngx_msec_t)30)
155	
156	static ngx_msec_t
157	omni_scheduler_recent_bucket_average(omni_global_state_t *gs, uint32_t batch_size)
158	{
159	    if (gs == NULL || batch_size == 0)
160	    {
161	        return 0;
162	    }
163	
164	    if (batch_size > OMNI_PREFILL_BATCH_STATS_MAX)
165	    {
166	        batch_size = OMNI_PREFILL_BATCH_STATS_MAX;
167	    }
168	
169	    omni_prefill_batch_stats_bucket_t *bucket = &gs->prefill_batch_stats.buckets[batch_size];
170	    if (bucket->count == 0)
171	    {
172	        return 0;
173	    }
174	
175	    if (bucket->cached_average > OMNI_SCHED_INFLITE_TIME*batch_size)
176	    {
177	        return bucket->cached_average - OMNI_SCHED_INFLITE_TIME*batch_size;
178	    }
179	
180	    return bucket->cached_average;
181	}
182	static ngx_msec_t
183	omni_scheduler_estimate_batch_exec_time(omni_global_state_t *gs, uint32_t batch_size)
184	{
185	    // Static baseline execution time mapping for small batch sizes.
186	    // These values represent empirical estimates for batch_size = 0, 1, 2, 3.
187	    static const ngx_msec_t exec_time_map[] = {0, 220, 280, 330, 380};
188	    static const size_t exec_time_map_len = sizeof(exec_time_map) / sizeof(exec_time_map[0]);
189	    if (batch_size == 0)
190	    {
191	        return 0;
192	    }
193	
194	    if (gs != NULL)
195	    {
196	        uint32_t capped_size = batch_size;
197	
198	        // Cap the batch size to prevent exceeding prefill statistics window.
199	        if (capped_size > OMNI_PREFILL_BATCH_STATS_MAX)
200	        {
201	            capped_size = OMNI_PREFILL_BATCH_STATS_MAX;
202	        }
203	
204	        // Try to get the recent average execution time for this batch size.
205	        ngx_msec_t recent = omni_scheduler_recent_bucket_average(gs, capped_size);
206	
207	        // ---------------------------------------------------------
208	        // Case 1.1: We have a valid recent value for this batch size.
209	        // ---------------------------------------------------------
210	        if (recent != 0)
211	        {
212	            // If actual batch size > capped size extrapolate upward.
213	            if (capped_size < batch_size)
214	            {
215	                uint32_t diff = batch_size - capped_size;
216	                uint64_t extended = (uint64_t)recent +
217	                                    (uint64_t)diff * (uint64_t)OMNI_SCHED_EXEC_TIME_INCREMENT;
218	
219	                // Clamp to max integer range.
220	                if (extended > OMNI_SCHED_EXEC_MAX_TIME)
221	                {
222	                    extended = OMNI_SCHED_EXEC_MAX_TIME;
223	                }
224	
225	                return (ngx_msec_t)extended;
226	            }
227	
228	            // Otherwise, return the observed average directly.
229	            return recent;
230	        }
231	
232	        // ---------------------------------------------------------
233	        // Case 1.2: No recent record for current batch size search smaller buckets.
234	        // ---------------------------------------------------------
235	        if (capped_size > 1)
236	        {
237	            for (uint32_t probe = capped_size - 1; probe > 0; probe--)
238	            {
239	                ngx_msec_t probe_recent = omni_scheduler_recent_bucket_average(gs, probe);
240	                if (probe_recent == 0)
241	                {
242	                    continue;
243	                }
244	
245	                // If the found probe size < current batch size extrapolate upward.
246	                if (probe < batch_size)
247	                {
248	                    uint32_t diff = batch_size - probe;
249	                    uint64_t extended = (uint64_t)probe_recent +
250	                                        (uint64_t)diff * (uint64_t)OMNI_SCHED_EXEC_TIME_INCREMENT;
251	
252	                    if (extended > OMNI_SCHED_EXEC_MAX_TIME)
253	                    {
254	                        extended = OMNI_SCHED_EXEC_MAX_TIME;
255	                    }
256	
257	                    return (ngx_msec_t)extended;
258	                }
259	
260	                // Otherwise, directly return the smaller bucket value.
261	                return probe_recent;
262	            }
263	        }
264	
265	        // ---------------------------------------------------------
266	        // Case 1.3: Still no valid smaller buckets search larger buckets.
267	        // ---------------------------------------------------------
268	        if (capped_size < OMNI_PREFILL_BATCH_STATS_MAX)
269	        {
270	            for (uint32_t probe = capped_size + 1; probe <= OMNI_PREFILL_BATCH_STATS_MAX; probe++)
271	            {
272	                ngx_msec_t probe_recent = omni_scheduler_recent_bucket_average(gs, probe);
273	                if (probe_recent == 0)
274	                {
275	                    continue;
276	                }
277	
278	                // If probe size < current extrapolate upward.
279	                if (probe < batch_size)
280	                {
281	                    uint32_t diff = batch_size - probe;
282	                    uint64_t extended = (uint64_t)probe_recent +
283	                                        (uint64_t)diff * (uint64_t)OMNI_SCHED_EXEC_TIME_INCREMENT;
284	
285	                    if (extended > OMNI_SCHED_EXEC_MAX_TIME)
286	                    {
287	                        extended = OMNI_SCHED_EXEC_MAX_TIME;
288	                    }
289	
290	                    return (ngx_msec_t)extended;
291	                }
292	
293	                // If probe size > current extrapolate downward.
294	                if (probe > batch_size)
295	                {
296	                    uint32_t diff = probe - batch_size;
297	                    ngx_msec_t reduced = probe_recent;
298	
299	                    // Prevent underflow: ensure reduced value stays positive.
300	                    if ((uint64_t)diff * (uint64_t)OMNI_SCHED_EXEC_TIME_INCREMENT >= (uint64_t)reduced)
301	                    {
302	                        reduced = OMNI_SCHED_EXEC_TIME_INCREMENT;
303	                    }
304	                    else
305	                    {
306	                        reduced -= diff * OMNI_SCHED_EXEC_TIME_INCREMENT;
307	                    }
308	
309	                    return reduced;
310	                }
311	
312	                // Exact match return it.
313	                return probe_recent;
314	            }
315	        }
316	    }
317	
318	    // =========================================================
319	    // Case 2: No valid statistics fallback to static baseline table.
320	    // =========================================================
321	    if (batch_size < exec_time_map_len)
322	    {
323	        // Return direct static mapping if within predefined table range.
324	        return exec_time_map[batch_size];
325	    }
326	
327	    // ---------------------------------------------------------
328	    // Case 3: Batch size exceeds static map range extrapolate linearly.
329	    // ---------------------------------------------------------
330	    uint32_t capped = (uint32_t)(exec_time_map_len - 1);
331	    uint32_t additional = batch_size - capped;
332	    uint64_t total = (uint64_t)exec_time_map[exec_time_map_len - 1] +
333	                     (uint64_t)additional * (uint64_t)OMNI_SCHED_EXEC_TIME_INCREMENT;
334	
335	    // Cap to prevent overflow.
336	    if (total > OMNI_SCHED_EXEC_MAX_TIME)
337	    {
338	        total = OMNI_SCHED_EXEC_MAX_TIME;
339	    }
340	
341	    // Final fallback estimated execution time.
342	    return (ngx_msec_t)total;
343	}
344	
345	// ============================================================================
346	// Estimate the expected finish time of a new task.
347	// This is a simple linear model: base_time + exec_time.
348	// The base time is either the last response timestamp or the current time.
349	// ============================================================================
350	static ngx_msec_t
351	omni_scheduler_estimate_finish_time(ngx_msec_t last_response_time, ngx_msec_t exec_time)
352	{
353	    return ngx_current_msec + exec_time;
354	}
355	
356	
357	// ============================================================================
358	// Select the prefill node expected to finish earliest.
359	// This function performs a heuristic scoring across all prefill endpoints,
360	// estimating their wait time, current load, and batch growth impact.
361	// ============================================================================
362	static ngx_int_t
363	omni_scheduler_select_earliest_prefill(omni_global_state_t *gs,
364	                                       ngx_http_omni_loc_conf_t *olcf,
365	                                       ngx_msec_t *estimated_finish)
366	{
367	    ngx_int_t selected = NGX_ERROR;
368	    ngx_msec_t best_finish = (ngx_msec_t)-1;
369	
370	    // Number of top candidates to consider for randomized selection.
371	    // Increasing top_k helps distribute load more evenly across prefill nodes.
372	    // Example:
373	    //   top_k = 1 deterministic best node (may cause load concentration)
374	    //   top_k = 3 pick randomly from top-3 candidates within threshold window
375	    ngx_uint_t top_k = 1;
376	    ngx_msec_t threshold_ms = OMNI_SCHED_EXEC_TIME_INCREMENT/2;
377	
378	    ngx_uint_t cand_idx[MAX_PREFILL_UPSTREAMS];
379	    ngx_msec_t cand_finish[MAX_PREFILL_UPSTREAMS];
380	    ngx_uint_t cand_count = 0;
381	
382	    uint16_t cnt = 0;
383	    for (uint32_t idx = 0; idx < MAX_PREFILL_UPSTREAMS && cnt < gs->num_prefill_endpoints; idx++)
384	    {
385	        omni_upstream_prefill_t *us = &gs->prefill_states[idx];
386	        if (us->comm.status != STATUS_ENABLE) {
387	            continue;
388	        }
389	        cnt++;
390	
391	        if (us->num_tokens > olcf->max_batch_num_token ||
392	            us->num_running > olcf->prefill_max_num_seqs)
393	        {
394	            continue;
395	        }
396	
397	        // Retrieve current batch execution metrics.
398	        omni_batch_metrics_t *current_batch = &us->his.his[us->his.head];
399	        uint32_t queued = us->num_queue;
400	        uint32_t executing = us->num_batch_exec;
401	
402	        // Projected batch size if this new request is added.
403	        uint32_t projected_batch_size = queued < UINT32_MAX ? (queued + 1) : UINT32_MAX;
404	
405	        // Estimate execution times for different states.
406	        ngx_msec_t current_exec_time = omni_scheduler_estimate_batch_exec_time(gs, executing);
407	        ngx_msec_t new_exec_time = omni_scheduler_estimate_batch_exec_time(gs, projected_batch_size);
408	        ngx_msec_t old_exec_time = omni_scheduler_estimate_batch_exec_time(gs, queued);
409	
410	        // Incremental delay added by joining current queue.
411	        ngx_msec_t incremental_exec = 0;
412	        if (new_exec_time > old_exec_time && old_exec_time !=0)
413	        {
414	            incremental_exec = new_exec_time - old_exec_time;
415	        }
416	
417	        if (current_batch->first_response_receive_time != 0
418	            && current_exec_time != 0
419	            && ngx_current_msec > current_batch->first_response_receive_time)
420	        {
421	            ngx_msec_t time_pass = ngx_current_msec - current_batch->first_response_receive_time + OMNI_SCHED_INFLITE_TIME;
422	            if (current_exec_time > time_pass)
423	            {
424	                current_exec_time -= time_pass;
425	            }
426	        }
427	
428	        // Compute total waiting time before this batch can finish.
429	        // uint64_t total_wait = (uint64_t)incremental_exec * (uint64_t)queued;
430	        uint64_t total_wait = (uint64_t)incremental_exec * (uint64_t)queued * (uint64_t)queued;
431	        total_wait += (uint64_t)new_exec_time;
432	        total_wait += (uint64_t)current_exec_time;
433	
434	        if (total_wait > NGX_MAX_UINT32_VALUE)
435	        {
436	            total_wait = NGX_MAX_UINT32_VALUE;
437	        }
438	
439	        ngx_msec_t wait_time = (ngx_msec_t)total_wait;
440	
441	        // Predict finish time using last response as temporal anchor.
442	        ngx_msec_t finish_time = omni_scheduler_estimate_finish_time(
443	            current_batch->first_response_receive_time,
444	            wait_time);
445	
446	        // Log each candidates evaluation details.
447	        ngx_log_error(NGX_LOG_INFO, ngx_cycle->log, 0,
448	            "[Prefill-Earliest] candidate=%ui executing=%ui first_response_receive_time=%M "
449	            "num_running=%ui queued=%ui total_wait=%M "
450	            "current_exec=%M new_exec=%M old_exec=%M wait_time=%M "
451	            "fin_time=%i estimated_finish=%M",
452	            idx,
453	            (ngx_uint_t)executing,
454	            current_batch->first_response_receive_time,
455	            (ngx_uint_t)us->num_running,
456	            (ngx_uint_t)queued,
457	            total_wait,
458	            current_exec_time,
459	            new_exec_time,
460	            old_exec_time,
461	            wait_time,
462	            (ngx_int_t)(finish_time - ngx_current_msec),
463	            finish_time);
464	
465	
466	        // Record candidate if within limits.
467	        if (cand_count < MAX_PREFILL_UPSTREAMS)
468	        {
469	            cand_idx[cand_count] = idx;
470	            cand_finish[cand_count] = finish_time;
471	            cand_count++;
472	        }
473	
474	        // Track the globally earliest finish.
475	        if (selected == NGX_ERROR || finish_time < best_finish)
476	        {
477	            selected = (ngx_int_t)idx;
478	            best_finish = finish_time;
479	        }
480	    }
481	
482	    // ------------------------------------------------------------------------
483	    // Step 2: No candidates available return error.
484	    // ------------------------------------------------------------------------
485	    if (cand_count == 0)
486	    {
487	        return NGX_ERROR;
488	    }
489	
490	    // ------------------------------------------------------------------------
491	    // Step 3: Filter out endpoints whose finish time exceeds threshold.
492	    // ------------------------------------------------------------------------
493	    ngx_uint_t filtered_idx[MAX_PREFILL_UPSTREAMS];
494	    ngx_msec_t filtered_finish[MAX_PREFILL_UPSTREAMS];
495	    ngx_uint_t filtered_count = 0;
496	
497	    for (ngx_uint_t i = 0; i < cand_count; i++)
498	    {
499	        if (cand_finish[i] <= best_finish + threshold_ms)
500	        {
501	            filtered_idx[filtered_count] = cand_idx[i];
502	            filtered_finish[filtered_count] = cand_finish[i];
503	            filtered_count++;
504	        }
505	    }
506	
507	    // ------------------------------------------------------------------------
508	    // Step 4: Sort filtered candidates by finish time ascending.
509	    // ------------------------------------------------------------------------
510	    for (ngx_uint_t i = 0; i < filtered_count && i < top_k; i++)
511	    {
512	        ngx_uint_t best_i = i;
513	        for (ngx_uint_t j = i + 1; j < filtered_count; j++)
514	        {
515	            if (filtered_finish[j] < filtered_finish[best_i])
516	            {
517	                best_i = j;
518	            }
519	        }
520	
521	        // Swap if necessary.
522	        if (best_i != i)
523	        {
524	            ngx_msec_t tmp_finish = filtered_finish[i];
525	            filtered_finish[i] = filtered_finish[best_i];
526	            filtered_finish[best_i] = tmp_finish;
527	
528	            ngx_uint_t tmp_idx = filtered_idx[i];
529	            filtered_idx[i] = filtered_idx[best_i];
530	            filtered_idx[best_i] = tmp_idx;
531	        }
532	    }
533	
534	    // Limit count to top_k candidates.
535	    if (filtered_count > top_k)
536	    {
537	        filtered_count = top_k;
538	    }
539	
540	    // ------------------------------------------------------------------------
541	    // Step 5: Randomized tie-breaking among top_k candidates within threshold.
542	    // ------------------------------------------------------------------------
543	    if (filtered_count > 0)
544	    {
545	        ngx_uint_t r = ((ngx_uint_t)ngx_random()) % filtered_count;
546	        selected = (ngx_int_t)filtered_idx[r];
547	        best_finish = filtered_finish[r];
548	
549	        ngx_log_error(NGX_LOG_DEBUG,
550	                      ngx_cycle->log,
551	                      0,
552	                      "[Prefill-Earliest] randomly selected idx=%ui among %ui candidates "
553	                      "(best=%M, threshold=%M, topk=%ui)",
554	                      filtered_idx[r],
555	                      filtered_count,
556	                      best_finish,
557	                      threshold_ms,
558	                      top_k);
559	    }
560	    else
561	    {
562	        // No candidates within acceptable threshold fallback to best only.
563	        ngx_log_error(NGX_LOG_INFO,
564	                      ngx_cycle->log,
565	                      0,
566	                      "[Prefill-Earliest] only best selected idx=%i (no candidates within threshold=%M)",
567	                      selected,
568	                      threshold_ms);
569	    }
570	
571	    // ------------------------------------------------------------------------
572	    // Step 6: Return the final selection and estimated finish time.
573	    // ------------------------------------------------------------------------
574	    if (selected != NGX_ERROR && estimated_finish != NULL)
575	    {
576	        *estimated_finish = best_finish;
577	    }
578	
579	    return selected;
580	}
581	
582	
583	static void update_prefill_weights(omni_req_group_t *group)
584	{
585	    uint32_t max_prompt_tokens = 0;
586	    ngx_msec_t max_wait_time = 0;
587	    for (uint32_t i = 0; i < group->watermark; i++)
588	    {
589	        omni_req_info_t *info = &group->requests[i];
590	        if (!info->in_use)
591	        {
592	            continue;
593	        }
594	        omni_req_t *req = omni_info_to_req(info);
595	
596	        if (max_prompt_tokens < req->metrics.prompt_num_tokens)
597	        {
598	            max_prompt_tokens = req->metrics.prompt_num_tokens;
599	        }
600	
601	        ngx_msec_t waited = ngx_current_msec - (ngx_msec_t) TIMEVAL_TO_MSEC(req->metrics.time_received);
602	        if (max_wait_time < waited)
603	        {
604	            max_wait_time = waited;
605	        }
606	    }
607	
608	    if (max_wait_time < 50)
609	    {
610	        max_wait_time = 50;
611	    }
612	
613	    for (uint32_t i = 0; i < group->watermark; i++)
614	    {
615	        omni_req_info_t *info = &group->requests[i];
616	        if (!info->in_use)
617	        {
618	            continue;
619	        }
620	        omni_req_t *req = omni_info_to_req(info);
621	
622	        ngx_msec_t waited = ngx_current_msec - (ngx_msec_t) TIMEVAL_TO_MSEC(req->metrics.time_received);
623	        double token_weight = (double)(max_prompt_tokens - req->metrics.prompt_num_tokens) / max_prompt_tokens;
624	        double time_weight = (double)waited / max_wait_time;
625	
626	        info->weight = token_weight * 0.8 + time_weight * 0.2;
627	    }
628	
629	    omni_sort_compact_group(group);
630	
631	    for (uint32_t idx = 0; idx < group->num_requests; idx++)
632	    {
633	        omni_req_info_t *info = &group->requests[idx];
634	        if (!info->in_use)
635	        {
636	            continue;
637	        }
638	        omni_req_t *req = omni_info_to_req(info);
639	        ngx_log_error(NGX_LOG_INFO, ngx_cycle->log, 0,
640	                      "[Prefill-Sort] Order %uD: slot=%uD tokens=%uD weight=%.2f",
641	                      idx,
642	                      info->slot_index,
643	                      req->metrics.prompt_num_tokens,
644	                      info->weight);
645	    }
646	}
647	
648	static void update_decode_weights(omni_req_group_t *group, uint32_t max_tokens_weight)
649	{
650	    uint32_t max_total_tokens = 1;
651	
652	    for (uint32_t i = 0; i < group->watermark; i++) {
653	        omni_req_info_t *info = &group->requests[i];
654	        if (!info->in_use) continue;
655	        omni_req_t *req = omni_info_to_req(info);
656	        if ((req->metrics.prompt_num_tokens + max_tokens_weight * req->metrics.max_tokens) > max_total_tokens) {
657	            max_total_tokens = req->metrics.prompt_num_tokens + max_tokens_weight * req->metrics.max_tokens;
658	        }
659	    }
660	
661	    for (uint32_t i = 0; i < group->watermark; i++) {
662	        omni_req_info_t *info = &group->requests[i];
663	        if (!info->in_use) continue;
664	        omni_req_t *req = omni_info_to_req(info);
665	        info->weight = ((double)req->metrics.prompt_num_tokens + (double)max_tokens_weight * (double)req->metrics.max_tokens)/ max_total_tokens;
666	    }
667	
668	    omni_sort_compact_group(group);
669	
670	    for (uint32_t idx = 0; idx < group->num_requests; idx++) {
671	        omni_req_info_t *info = &group->requests[idx];
672	        if (!info->in_use) {
673	            continue;
674	        }
675	        omni_req_t *req = omni_info_to_req(info);
676	        ngx_log_error(NGX_LOG_INFO, ngx_cycle->log, 0,
677	                      "[Decode-Sort] Order %uD: slot=%uD total_tokens=%uD prompt_num_tokens=%uD max_tokens=%uD max_tokens_weight=%uD weight=%.2f",
678	                      idx,
679	                      info->slot_index,
680	                      req->metrics.prompt_num_tokens + max_tokens_weight * req->metrics.max_tokens,
681	                      req->metrics.prompt_num_tokens,
682	                      req->metrics.max_tokens,
683	                      max_tokens_weight,
684	                      info->weight);
685	    }
686	}
687	
688	void omni_proxy_schedule_prefill(omni_global_state_t *gs, ngx_http_omni_loc_conf_t *olcf)
689	{
690	    omni_req_group_t *group = &gs->groups[PHASE_PREFILL_WAITING_SCHEDULE];
691	
692	    if (gs->num_prefill_endpoints == 0)
693	    {
694	        return;
695	    }
696	
697	    // TODO: Check should schedule or wait based on upstream expected come back time
698	
699	    update_prefill_weights(group);
700	
701	    for (uint32_t i = 0; i < group->num_requests; i++)
702	    {
703	        omni_req_info_t *info = &group->requests[i];
704	        omni_req_t *req = omni_info_to_req(info);
705	
706	        if (!omni_req_is_in_phase(req, PHASE_PREFILL_WAITING_SCHEDULE))
707	        {
708	            ngx_log_error(NGX_LOG_ERR, ngx_cycle->log, 0,
709	                          "omni_proxy_schedule_prefill: req %ui not in PREFILL_WAITING_SCHEDULE phase", req->slot_index);
710	            continue;
711	        }
712	
713	        uint32_t selected = (uint32_t)ngx_random() % gs->num_prefill_endpoints;
714	        uint32_t best_match = 0;
715	        uint32_t best_load_tokens = UINT32_MAX;
716	        uint32_t best_running = UINT32_MAX;
717	        uint32_t best_idx = UINT32_MAX;
718	        ngx_flag_t used_earliest_algo = 0;
719	        ngx_msec_t algo_estimated_time = 0;
720	        uint16_t cnt = 0;
721	
722	        if (olcf->schedule_algo == OMNI_PROXY_SCHEDULE_ALGO_EARLIEST_BATCH)
723	        {
724	            ngx_int_t algo_selected = omni_scheduler_select_earliest_prefill(gs, olcf, &algo_estimated_time);
725	            if (algo_selected != NGX_ERROR)
726	            {
727	                selected = (uint32_t)algo_selected;
728	                used_earliest_algo = 1;
729	
730	                ngx_msec_t now_ms = ngx_current_msec;
731	                ngx_msec_t delta_ms = algo_estimated_time - now_ms;
732	
733	                struct timeval est_tv;
734	                omni_get_current_time(&est_tv);
735	                est_tv.tv_sec += (long)(delta_ms / (ngx_msec_t)1000);
736	                est_tv.tv_usec += (long)((delta_ms % (ngx_msec_t)1000) * (ngx_msec_t)1000);
737	                if (est_tv.tv_usec >= 1000000)
738	                {
739	                    est_tv.tv_sec += est_tv.tv_usec / 1000000;
740	                    est_tv.tv_usec = est_tv.tv_usec % 1000000;
741	                }
742	
743	                ngx_log_error(NGX_LOG_INFO, ngx_cycle->log, 0,
744	                            "[Prefill-%d] earliest-batch scheduler picked endpoint %d "
745	                            "(estimated_finish=%M => %d.%06d), RequestID:%s",
746	                            req->slot_index,
747	                            selected,
748	                            algo_estimated_time,
749	                            (long)est_tv.tv_sec,
750	                            (long)est_tv.tv_usec,
751	                            req->request_id);
752	            }
753	            else
754	            {
755	                ngx_log_error(NGX_LOG_WARN, ngx_cycle->log, 0,
756	                              "[Prefill-%d] earliest-batch scheduler had no candidate, falling back to default",
757	                              req->slot_index);
758	            }
759	        }
760	
761	        if (!used_earliest_algo)
762	        {
763	            for (uint32_t j = 0; j < MAX_PREFILL_UPSTREAMS && cnt < gs->num_prefill_endpoints; j++)
764	            {
765	                if (gs->prefill_states[j].comm.status != STATUS_ENABLE) {
766	                    continue;
767	                }
768	                cnt++;
769	                uint32_t m = req->prefill_match_depths[j];
770	
771	                uint32_t load_tokens = gs->prefill_states[j].num_tokens;
772	                uint32_t running = gs->prefill_states[j].num_running;
773	                if (load_tokens > olcf->max_batch_num_token || running > olcf->prefill_max_num_seqs)
774	                {
775	                    continue;
776	                }
777	                if (m > best_match ||
778	                    (m == best_match && load_tokens < best_load_tokens) ||
779	                    (m == best_match && load_tokens == best_load_tokens && running < best_running))
780	                {
781	                    best_match = m;
782	                    best_load_tokens = load_tokens;
783	                    best_running = running;
784	                    best_idx = j;
785	                }
786	            }
787	
788	            if (best_match > 0 && best_idx != UINT32_MAX)
789	            {
790	                selected = best_idx;
791	                ngx_log_error(NGX_LOG_INFO, ngx_cycle->log, 0, "[Prefill-%d] Prefix cache hit on: %d with match_depth %d",
792	                              req->slot_index, selected, req->prefill_match_depths[selected]);
793	            } else {
794	                uint32_t least_load = UINT32_MAX;
795	                for (uint32_t mi = gs->last_selected_prefill, loop_cnt = 0;
796	                    mi < MAX_PREFILL_UPSTREAMS + gs->last_selected_prefill && loop_cnt < gs->num_prefill_endpoints; mi++) {
797	                    uint32_t j = mi % MAX_PREFILL_UPSTREAMS;
798	                    omni_upstream_prefill_t *prefill = &gs->prefill_states[j];
799	                    if (prefill->comm.status != STATUS_ENABLE) {
800	                        if (prefill->comm.status == STATUS_UNUSED) {
801	                            mi = MAX_PREFILL_UPSTREAMS - 1; /* skip unuse upstream and start from 0 */
802	                        }
803	                        continue;
804	                    }
805	                    loop_cnt++;
806	                    if (gs->prefill_states[j].num_tokens < least_load)
807	                    {
808	                        least_load = gs->prefill_states[j].num_tokens;
809	                        selected = j;
810	                        if (least_load == 0)
811	                        {
812	                            break;
813	                        }
814	                    }
815	                }
816	                ngx_log_error(NGX_LOG_INFO,
817	                              ngx_cycle->log,
818	                              0,
819	                              "[Prefill-%d] No Prefix cache hit, choose least workload Prefill %d with load %d",
820	                              req->slot_index,
821	                              selected,
822	                              least_load);
823	            }
824	        }
825	
826	        omni_upstream_prefill_t *selected_prefill = &gs->prefill_states[selected];
827	        req->prefill_upstream_endpoint_idx = selected;
828	        req->prefill_group_id = selected_prefill->comm.group_id;
829	        gs->last_selected_prefill = selected + 1;
830	
831	        if (selected_prefill->num_running == 0)
832	        {
833	            selected_prefill->num_batch_exec = 1;
834	            selected_prefill->num_queue = 0;
835	            selected_prefill->idle_batch = true;
836	        }
837	        else
838	        {
839	            selected_prefill->num_queue++;
840	        }
841	
842	        ngx_atomic_fetch_add(&selected_prefill->num_running, 1);
843	        ngx_atomic_fetch_add(&selected_prefill->num_tokens, req->metrics.prompt_num_tokens);
844	        ngx_atomic_fetch_add(&selected_prefill->comm.ref, 1);
845	
846	        omni_global_phase_change_to(req, PHASE_PREFILL_WAITING_SCHEDULE, PHASE_PREFILL_SCHEDULED);
847	        req->has_prefill_sched = true;
848	        struct timeval tv;
849	        omni_get_current_time(&tv);
850	        req->metrics.time_prefill_scheduled = tv;
851	        ngx_log_error(NGX_LOG_INFO, ngx_cycle->log, 0,
852	                            "<<<Action: Enter state P scheduled; Timestamp:%d.%06d; RequestID:%s", tv.tv_sec, tv.tv_usec, req->request_id);
853	
854	        ngx_log_error(NGX_LOG_INFO, ngx_cycle->log, 0, "[Prefill-%d] Schedule to: %d (group=%uD)",
855	                      req->slot_index, req->prefill_upstream_endpoint_idx, req->prefill_group_id);
856	    }
857	
858	    // TODO: estimated expected next schedule time
859	}
860	
861	void omni_proxy_schedule_decode(omni_global_state_t *gs, ngx_http_omni_loc_conf_t *olcf)
862	{
863	    omni_req_group_t *group = &gs->groups[PHASE_DECODE_WAITING_SCHEDULE];
864	    // TODO: Check should schedule or wait based on upstream expected come back time
865	    // TODO: Here we can do some estimation of pull kv finish time to make sure pull kv
866	    // workloads are balanced
867	
868	    update_decode_weights(group, olcf->max_tokens_weight);
869	
870	    for (size_t i = 0; i < group->watermark; i++)
871	    {
872	        omni_req_info_t *info = &group->requests[i];
873	        if (!info->in_use)
874	        {
875	            continue;
876	        }
877	        omni_req_t *req = omni_info_to_req(info);
878	        if (!omni_req_is_in_phase(req, PHASE_DECODE_WAITING_SCHEDULE))
879	        {
880	            ngx_log_error(NGX_LOG_ERR, ngx_cycle->log, 0,
881	                          "omni_proxy_schedule_decode: req %ui not in DECODE_WAITING_SCHEDULE phase", req->slot_index);
882	            continue;
883	        }
884	
885	        uint32_t least_load = UINT32_MAX;
886	        uint32_t selected = UINT32_MAX;
887	        uint32_t cnt = 0;
888	        uint32_t matched_cnt = 0;
889	
890	        uint32_t best_match = 0;
891	        uint32_t best_load_tokens = UINT32_MAX;
892	        uint32_t best_running = UINT32_MAX;
893	        uint32_t best_idx = UINT32_MAX;
894	
895	        for (uint32_t j = 0; j < MAX_DECODE_UPSTREAMS && cnt < gs->num_decode_endpoints; j++)
896	        {
897	            if (gs->decode_states[j].comm.status != STATUS_ENABLE){
898	                continue;
899	            }
900	            cnt++;
901	            if (gs->decode_states[j].comm.group_id != req->prefill_group_id)
902	            {
903	                continue;
904	            }
905	            
906	            uint32_t m = req->decode_match_depths[j];
907	
908	            uint32_t load_tokens = gs->decode_states[j].num_tokens;
909	            uint32_t running = gs->decode_states[j].num_running;
910	            if (running > olcf->decode_max_num_seqs)
911	            {
912	                continue;
913	            }
914	            if (m > best_match ||
915	                (m == best_match && load_tokens < best_load_tokens) ||
916	                (m == best_match && load_tokens == best_load_tokens && running < best_running))
917	            {
918	                best_match = m;
919	                best_load_tokens = load_tokens;
920	                best_running = running;
921	                best_idx = j;
922	            }
923	        }
924	        cnt = 0;
925	        for (int m = gs->last_selected_decode;
926	            m < MAX_DECODE_UPSTREAMS + gs->last_selected_decode && cnt < gs->num_decode_endpoints; m++) {
927	            int j = m % MAX_DECODE_UPSTREAMS;
928	            omni_upstream_decode_t *decode = &gs->decode_states[j];
929	            if (decode->comm.status != STATUS_ENABLE) {
930	                if (decode->comm.status == STATUS_UNUSED) {
931	                    m = MAX_DECODE_UPSTREAMS - 1; /* skip unuse upstream and start from 0 */
932	                }
933	                continue;
934	            }
935	            cnt++;
936	            if (decode->comm.group_id != req->prefill_group_id) {
937	                continue;
938	            }
939	
940	            gs->group_matched_idx[matched_cnt] = (uint32_t)j;
941	            matched_cnt++;
942	
943	            if (gs->decode_states[j].num_tokens < least_load && gs->decode_states[j].num_running < olcf->decode_max_num_seqs)
944	            {
945	                least_load = gs->decode_states[j].num_tokens;
946	                selected = (uint32_t)j;
947	                if (least_load == 0)
948	                {
949	                    break;
950	                }
951	            }
952	        }
953	        
954	        if (selected == UINT32_MAX) {
955	            if (matched_cnt == 0) {
956	                ngx_log_error(NGX_LOG_WARN, ngx_cycle->log, 0,
957	                    "omni_proxy_schedule_decode: invalid matched_cnt=%ui, skip scheduling for request_id=%s",
958	                    matched_cnt, req->request_id);
959	                continue;
960	            }
961	            ngx_uint_t rand_idx = (ngx_uint_t)((uint32_t)ngx_random() % matched_cnt);
962	            selected = gs->group_matched_idx[rand_idx];
963	        }
964	
965	        req->decode_upstream_endpoint_idx = (uint16_t)selected;
966	        gs->last_selected_decode = (uint16_t)(selected + 1U);
967	        ngx_atomic_fetch_add(&gs->decode_states[selected].num_running, 1);
968	        ngx_atomic_fetch_add(&gs->decode_states[selected].num_tokens, req->metrics.prompt_num_tokens);
969	        ngx_atomic_fetch_add(&gs->decode_states[selected].comm.ref, 1);
970	
971	        omni_global_phase_change_to(req, PHASE_DECODE_WAITING_SCHEDULE, PHASE_DECODE_SCHEDULED);
972	        req->has_decode_sched = true;
973	
974	        struct timeval tv;
975	        omni_get_current_time(&tv);
976	        req->metrics.time_decode_scheduled = tv;
977	
978	        ngx_log_error(NGX_LOG_INFO, ngx_cycle->log, 0,
979	                            "<<<Action: Enter state D scheduled; Timestamp:%d.%06d; RequestID:%s", tv.tv_sec, tv.tv_usec, req->request_id);
980	
981	        ngx_log_error(NGX_LOG_INFO, ngx_cycle->log, 0,
982	                      "[Decode-%d] Schedule to: %d (load=%ui, group=%ui)",
983	                      req->slot_index,
984	                      req->decode_upstream_endpoint_idx,
985	                      gs->decode_states[selected].num_tokens,
986	                      gs->decode_states[selected].comm.group_id);
987	    }
988	}
