4	#include "omni_radix_tree.h"
5	#include "omni_utils.h"
6	#include <limits.h>
7	
8	/*
9	 switch rbtree keying from edge-id (H(parent, child))
10	 to node-id (child_hash). Requires per-node parent pointer to maintain
11	 parent/child linked lists and to allow O(1) unlink when removing a node
12	 found via child_hash lookup.
13	
14	 Assumptions / notes:
15	 - Each tree (per prefill server) guarantees child_hash uniqueness within the tree.
16	 - ngx_rbtree_key_t may be narrower than uint64_t on some platforms; we cast
17	   child_hash to ngx_rbtree_key_t. If you need full 64-bit key portability
18	   on 32-bit platforms, additional handling is required.
19	*/
20	
21	omni_radix_tree_t *omni_radix_tree_init(ngx_slab_pool_t *shpool)
22	{
23	    omni_radix_tree_t *tree;
24	
25	    tree = ngx_slab_alloc(shpool, sizeof(omni_radix_tree_t));
26	    if (tree == NULL)
27	    {
28	        return NULL;
29	    }
30	
31	    ngx_memzero(tree, sizeof(omni_radix_tree_t));
32	    tree->shpool = shpool;
33	    tree->version = 1;
34	
35	    if (ngx_shmtx_create(&tree->mutex, &tree->lock, "radix lock") != NGX_OK)
36	    {
37	        ngx_slab_free(shpool, tree);
38	        return NULL;
39	    }
40	
41	    ngx_rbtree_init(&tree->lookup_tree, &tree->sentinel, ngx_rbtree_insert_value);
42	
43	    tree->root = ngx_slab_alloc(shpool, sizeof(omni_radix_node_t));
44	    if (tree->root == NULL)
45	    {
46	        ngx_shmtx_destroy(&tree->mutex);
47	        ngx_slab_free(shpool, tree);
48	        return NULL;
49	    }
50	
51	    ngx_memzero(tree->root, sizeof(omni_radix_node_t));
52	    tree->root->hash_key = 0;
53	    tree->root->parent = NULL;
54	    /* Use child_hash (here 0) as rbtree key for the root */
55	    tree->root->rb_node.key = (ngx_rbtree_key_t)tree->root->hash_key;
56	
57	    ngx_rbtree_insert(&tree->lookup_tree, &tree->root->rb_node);
58	
59	    tree->writer_pid = ngx_pid;
60	
61	    return tree;
62	}
63	
64	static omni_radix_node_t *omni_find_node(omni_radix_tree_t *tree, uint64_t parent_hash, uint64_t child_hash)
65	{
66	    ngx_rbtree_node_t *node;
67	    ngx_rbtree_key_t target_key = (ngx_rbtree_key_t)child_hash;
68	
69	    node = tree->lookup_tree.root;
70	    while (node != NULL && node != &tree->sentinel)
71	    {
72	        if (target_key < node->key)
73	        {
74	            node = node->left;
75	        }
76	        else if (target_key > node->key)
77	        {
78	            node = node->right;
79	        }
80	        else
81	        {
82	            omni_radix_node_t *orn = (omni_radix_node_t *)node;
83	            /* If caller does not care about parent, return first match */
84	            if (parent_hash == UINT64_MAX)
85	            {
86	                return orn;
87	            }
88	            /* Verify parent matches expected parent_hash */
89	            if (orn->parent && orn->parent->hash_key == parent_hash)
90	            {
91	                return orn;
92	            }
93	            /* Found node with that child_hash but parent doesn't match */
94	            return NULL;
95	        }
96	    }
97	
98	    return NULL;
99	}
100	
101	ngx_int_t omni_radix_tree_add_chain(omni_radix_tree_t *tree, uint64_t *hash_chain,
102	                                    ngx_uint_t chain_len)
103	{
104	    omni_radix_node_t *current, *new_node;
105	    ngx_uint_t i;
106	
107	    if (chain_len == 0 || hash_chain == NULL)
108	    {
109	        return NGX_ERROR;
110	    }
111	
112	    ngx_shmtx_lock(&tree->mutex);
113	
114	    current = tree->root;
115	
116	    for (i = 0; i < chain_len; i++)
117	    {
118	        uint64_t current_hash = hash_chain[i];
119	        omni_radix_node_t *existing;
120	
121	        /* Find child node by child_hash and verify parent == current->hash_key */
122	        existing = omni_find_node(tree, current->hash_key, current_hash);
123	
124	        if (existing != NULL)
125	        {
126	            current = existing;
127	            continue;
128	        }
129	
130	        new_node = ngx_slab_alloc(tree->shpool, sizeof(omni_radix_node_t));
131	        if (new_node == NULL)
132	        {
133	            ngx_shmtx_unlock(&tree->mutex);
134	            return NGX_ERROR;
135	        }
136	
137	        ngx_memzero(new_node, sizeof(omni_radix_node_t));
138	        new_node->hash_key = current_hash;
139	        new_node->parent = current; /* set parent pointer */
140	
141	        /* rbtree key is the child hash (node id) */
142	        new_node->rb_node.key = (ngx_rbtree_key_t)new_node->hash_key;
143	
144	        new_node->next_sibling = current->first_child;
145	        current->first_child = new_node;
146	
147	        ngx_rbtree_insert(&tree->lookup_tree, &new_node->rb_node);
148	
149	        current = new_node;
150	    }
151	
152	    tree->version++;
153	
154	    ngx_shmtx_unlock(&tree->mutex);
155	    return NGX_OK;
156	}
157	
158	ngx_uint_t omni_radix_tree_match(omni_radix_tree_t *tree, uint64_t *hash_chain,
159	                                 ngx_uint_t chain_len)
160	{
161	    omni_radix_node_t *current;
162	    ngx_uint_t match_depth = 0;
163	    ngx_uint_t i;
164	
165	    if (chain_len == 0 || hash_chain == NULL)
166	    {
167	        return 0;
168	    }
169	
170	    ngx_shmtx_lock(&tree->mutex);
171	
172	    current = tree->root;
173	
174	    for (i = 0; i < chain_len; i++)
175	    {
176	        uint64_t current_hash = hash_chain[i];
177	        omni_radix_node_t *next;
178	
179	        /* Search by child_hash and verify the returned node's parent is current */
180	        next = omni_find_node(tree, current->hash_key, current_hash);
181	
182	        if (next == NULL)
183	        {
184	            break;
185	        }
186	
187	        if (next != tree->root)
188	        {
189	            match_depth++;
190	        }
191	
192	        current = next;
193	    }
194	
195	    ngx_shmtx_unlock(&tree->mutex);
196	    return match_depth;
197	}
198	
199	ngx_uint_t omni_radix_tree_match_optimistic(omni_radix_tree_t *tree, uint64_t *hash_chain,
200	                                            ngx_uint_t chain_len)
201	{
202	    omni_radix_node_t *current;
203	    ngx_uint_t match_depth = 0;
204	    ngx_uint_t i, start_version;
205	
206	    if (chain_len == 0 || hash_chain == NULL)
207	    {
208	        return 0;
209	    }
210	
211	    do
212	    {
213	        ngx_memory_barrier();
214	        start_version = tree->version;
215	
216	        current = tree->root;
217	        match_depth = 0;
218	
219	        for (i = 0; i < chain_len; i++)
220	        {
221	            uint64_t current_hash = hash_chain[i];
222	            omni_radix_node_t *next;
223	            ngx_rbtree_key_t target = (ngx_rbtree_key_t)current_hash;
224	            ngx_rbtree_node_t *node = tree->lookup_tree.root;
225	
226	            while (node != NULL && node != &tree->sentinel)
227	            {
228	                if (target < node->key)
229	                {
230	                    node = node->left;
231	                }
232	                else if (target > node->key)
233	                {
234	                    node = node->right;
235	                }
236	                else
237	                {
238	                    next = (omni_radix_node_t *)node;
239	                    break;
240	                }
241	            }
242	
243	            if (node == &tree->sentinel)
244	            {
245	                break;
246	            }
247	
248	            /* Verify parent relationship matches current */
249	            if (next->parent == NULL || next->parent->hash_key != current->hash_key)
250	            {
251	                break;
252	            }
253	
254	            match_depth++;
255	            current = next;
256	        }
257	
258	        ngx_memory_barrier();
259	    } while (tree->version != start_version);
260	
261	    return match_depth;
262	}
263	
264	static void omni_recursive_remove(omni_radix_tree_t *tree, omni_radix_node_t *root)
265	{
266	    if (root == NULL) {
267	        return;
268	    }
269	
270	    omni_radix_node_t *work, *current, *child, *tmp, *head;
271	
272	    root->next_sibling = NULL;
273	
274	    /* Phase 1: Flatten subtree into a post-order linked list.
275	     * work list holds nodes whose subtrees still need processing.
276	     * head list accumulates nodes in post-order (children before parent).
277	     * O(1) auxiliary space — only pointer reassignments. */
278	    head = NULL;
279	    work = root;
280	
281	    while (work != NULL) {
282	        current = work;
283	        work = current->next_sibling;
284	
285	        child = current->first_child;
286	        while (child != NULL) {
287	            tmp = child->next_sibling;
288	            child->next_sibling = work;
289	            work = child;
290	            child = tmp;
291	        }
292	        current->first_child = NULL;
293	
294	        current->next_sibling = head;
295	        head = current;
296	    }
297	
298	    /* Phase 2: Delete all nodes linearly in post-order */
299	    while (head != NULL) {
300	        current = head;
301	        head = current->next_sibling;
302	        ngx_rbtree_delete(&tree->lookup_tree, &current->rb_node);
303	        ngx_slab_free(tree->shpool, current);
304	    }
305	}
306	
307	static void omni_remove_from_parent(omni_radix_tree_t *tree, omni_radix_node_t *parent,
308	                                    omni_radix_node_t *node)
309	{
310	    omni_radix_node_t *prev, *current;
311	
312	    if (parent == NULL || node == NULL)
313	    {
314	        return;
315	    }
316	
317	    if (parent->first_child == node)
318	    {
319	        parent->first_child = node->next_sibling;
320	        return;
321	    }
322	
323	    prev = NULL;
324	    current = parent->first_child;
325	
326	    while (current != NULL && current != node)
327	    {
328	        prev = current;
329	        current = current->next_sibling;
330	    }
331	
332	    if (current == node && prev != NULL)
333	    {
334	        prev->next_sibling = node->next_sibling;
335	    }
336	}
337	
338	ngx_int_t omni_radix_tree_remove(omni_radix_tree_t *tree, uint64_t hash_to_remove)
339	{
340	    omni_radix_node_t *node_to_remove;
341	
342	    ngx_shmtx_lock(&tree->mutex);
343	
344	    /* Find node by child_hash (parent unspecified) */
345	    node_to_remove = omni_find_node(tree, UINT64_MAX, hash_to_remove);
346	
347	    if (node_to_remove == NULL)
348	    {
349	        ngx_shmtx_unlock(&tree->mutex);
350	        return NGX_ERROR;
351	    }
352	
353	    /* Use the stored parent pointer for unlink */
354	    omni_remove_from_parent(tree, node_to_remove->parent, node_to_remove);
355	
356	    omni_recursive_remove(tree, node_to_remove);
357	
358	    tree->version++;
359	
360	    ngx_shmtx_unlock(&tree->mutex);
361	    return NGX_OK;
362	}
363	
364	void omni_radix_tree_destroy(omni_radix_tree_t *tree)
365	{
366	    if (tree == NULL)
367	    {
368	        return;
369	    }
370	
371	    ngx_shmtx_lock(&tree->mutex);
372	
373	    omni_recursive_remove(tree, tree->root);
374	
375	    ngx_shmtx_destroy(&tree->mutex);
376	
377	    ngx_slab_free(tree->shpool, tree);
378	}
379	
380	typedef ngx_uint_t (*omni_matcher)(omni_radix_tree_t *tree, uint64_t *hash_chain,
381	                                   ngx_uint_t chain_len);
382	
383	static ngx_int_t omni_radix_tree_test_internal(omni_radix_tree_t *tree, omni_matcher matcher)
384	{
