    {
        ngx_log_error(NGX_LOG_ERR, ngx_cycle->log, 0,
                      "radix_tree_test: add_chain failed in test 1");
        return NGX_ERROR;
    }

    match_depth = matcher(tree, chain1, 2);
    if (match_depth != 2)
