        return NGX_ERROR;
    }

    // Test 15: Test chain with zero as data value (not root)
    printf("Test 15: Chain with zero data value\n");
    uint64_t chain7[] = {123, 0, 456};
    if (omni_radix_tree_add_chain(tree, chain7, 3) != NGX_OK)
    {
