189	static void omni_req_free(omni_req_t *req)
190	{
191	    ngx_http_request_t *r = omni_get_http_request(req);
192	    ngx_log_error(NGX_LOG_INFO, r->connection->log, 0, "Free Req:%d, at:%u",
193	                  req->slot_index, req->phase_state);
194	    ngx_shmtx_lock(&g_state->shmtx);
195	    omni_free_request(&g_state->request_pool, req);
196	    ngx_shmtx_unlock(&g_state->shmtx);
197	}
198	
199	void omni_phase_transition_all(omni_req_t *req, omni_proxy_request_phase_t from, omni_proxy_request_phase_t to)
200	{
201	    omni_local_phase_change_to(req, from, to);
202	
203	    ngx_shmtx_lock(&g_state->shmtx);
204	    omni_global_phase_change_to(req, from, to);
205	    omni_req_leave_phase(req, from);
206	    omni_req_enter_phase(req, to);
207	    ngx_shmtx_unlock(&g_state->shmtx);
208	}
209	
210	static inline omni_req_context_t *omni_get_req_ctx(ngx_http_request_t *r)
211	{
212	    return ngx_http_get_module_ctx(r, ngx_http_omni_proxy_module);
213	}
214	
215	
216	static inline omni_req_t *omni_get_req(ngx_http_request_t *r)
217	{
218	    omni_req_context_t *ctx = omni_get_req_ctx(r);
219	    if (ctx == NULL){
220	        ngx_log_error(NGX_LOG_NOTICE, r->connection->log, 0,
221	            "omni_get_req: Failed to get request context for a request that should have one, not a omni req.");
222	        return NULL;
223	    }
224	    return ctx->req;
225	}
226	
227	static void omni_proxy_post_tokenized(omni_req_t *req)
228	{
229	    ngx_shmtx_lock(&g_state->shmtx);
230	    uint16_t num_prefill = g_state->num_prefill_endpoints;
231	    uint16_t num_decode = g_state->num_decode_endpoints;
232	    ngx_shmtx_unlock(&g_state->shmtx);
233	
234	    // Prefill Matching
235	    uint32_t local_prefill_match_depths[MAX_PREFILL_UPSTREAMS];
236	    ngx_uint_t computed_max_prefill = 0;
237	
238	    for (uint16_t i = 0, cnt = 0; i < MAX_PREFILL_UPSTREAMS && cnt < num_prefill; i++) {
239	        ngx_uint_t match_depth = 0;
240	        ngx_shmtx_lock(&g_state->shmtx);
241	        omni_upstream_prefill_t *prefill = &g_state->prefill_states[i];
242	        if (prefill->comm.status == STATUS_ENABLE) {
243	            omni_radix_tree_t *tree = prefill->radix_tree;
244	            cnt++;
245	            if (tree != NULL) {
246	                match_depth = omni_radix_tree_match_optimistic(tree,
247	                                                                (uint64_t *)req->tokenizer_req.block_hashes,
248	                                                                req->tokenizer_req.block_hashes_len);
249	            }
250	        }
251	        ngx_shmtx_unlock(&g_state->shmtx);
252	
253	        local_prefill_match_depths[i] = (uint32_t)match_depth;
254	        if (match_depth > 0) {
255	            ngx_log_error(NGX_LOG_INFO,
256	                omni_get_http_request(req)->connection->log,
257	                0,
258	                "[APC_MATCHING-%d] prefill[%ui] match_depth=%ui",
259	                req->slot_index,
260	                i,
261	                local_prefill_match_depths[i]);
262	        }
263	
264	        if ((ngx_uint_t)match_depth > computed_max_prefill)
265	            computed_max_prefill = match_depth;
266	    }
267	
268	    ngx_log_error(NGX_LOG_INFO,
269	                  omni_get_http_request(req)->connection->log,
